+func TestEnvSubstitutionHook(t *testing.T) {
+	t.Setenv("CONFIG_VALUE", "resolved")
+	t.Setenv("_CONFIG_2", "")
+
+	hook := envSubstitutionHookFunc().(func(reflect.Kind, reflect.Kind, interface{}) (interface{}, error))
+	for _, tt := range []struct {
+		name  string
+		from  reflect.Kind
+		input interface{}
+		want  interface{}
+	}{
+		{"set variable", reflect.String, "${CONFIG_VALUE}", "resolved"},
+		{"empty variable", reflect.String, "${_CONFIG_2}", ""},
+		{"unset variable", reflect.String, "${CONFIG_MISSING}", "${CONFIG_MISSING}"},
+		{"embedded reference", reflect.String, "prefix-${CONFIG_VALUE}", "prefix-${CONFIG_VALUE}"},
+		{"trailing text", reflect.String, "${CONFIG_VALUE}-suffix", "${CONFIG_VALUE}-suffix"},
+		{"invalid first character", reflect.String, "${1CONFIG}", "${1CONFIG}"},
+		{"invalid character", reflect.String, "${CONFIG-VALUE}", "${CONFIG-VALUE}"},
+		{"named string", reflect.String, LogEncodingJSON, LogEncodingJSON},
+		{"non-string", reflect.Int, 42, 42},
+	} {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := hook(tt.from, reflect.String, tt.input)
+			require.NoError(t, err)
+			assert.Equal(t, tt.want, got)
+		})
+	}
+}
+
+func TestLoadEnvReferences(t *testing.T) {
+	path := filepath.Join(t.TempDir(), "config.yml")
+	require.NoError(t, os.WriteFile(path, []byte(`server:
+  http_port: ${CONFIG_PORT}
+log:
+  encoding: ${CONFIG_ENCODING}
+  file: ${CONFIG_FILE}
+`), 0600))
+	t.Setenv("CONFIG_PORT", "8081")
+	t.Setenv("CONFIG_ENCODING", "json")
+	t.Setenv("CONFIG_FILE", "events.log")
+
+	res, err := Load(context.Background(), path)
+	require.NoError(t, err)
+	assert.Equal(t, 8081, res.Config.Server.HTTPPort)
+	assert.Equal(t, LogEncodingJSON, res.Config.Log.Encoding)
+	assert.Equal(t, "events.log", res.Config.Log.File)
+
+	t.Setenv("FLIPT_SERVER_HTTP_PORT", "9090")
+	t.Setenv("FLIPT_LOG_ENCODING", "console")
+	res, err = Load(context.Background(), path)
+	require.NoError(t, err)
+	assert.Equal(t, 9090, res.Config.Server.HTTPPort)
+	assert.Equal(t, LogEncodingConsole, res.Config.Log.Encoding)
+}
